CREATE TABLE units
WITH (format = 'PARQUET', write_compression = 'SNAPPY', external_location = '{loc}/units/') AS
SELECT
  id AS unit_id,
  patient_id,
  t_start AS enc_start,
  t_end AS enc_end
FROM res_index
WHERE
  is_unit AND NOT patient_id IS NULL;

CREATE TABLE unit_bound
WITH (format = 'PARQUET', write_compression = 'SNAPPY', external_location = '{loc}/unit_bound/') AS
WITH enc AS (
  SELECT
    id,
    patient_id,
    t_start,
    t_end
  FROM res_index
  WHERE
    rtype = 'Encounter'
), step1 AS (
  SELECT
    u.unit_id,
    u.patient_id,
    u.enc_start,
    u.enc_end,
    LEAST(u.enc_start, COALESCE(MIN(e.t_start), u.enc_start)) AS v_lo
  FROM units AS u
  LEFT JOIN enc AS e
    ON e.patient_id = u.patient_id
    AND e.id <> u.unit_id
    AND e.t_end >= u.enc_start - INTERVAL '1' HOUR
    AND e.t_end <= u.enc_start
  GROUP BY
    u.unit_id,
    u.patient_id,
    u.enc_start,
    u.enc_end
), step2 AS (
  SELECT
    s.unit_id,
    s.patient_id,
    s.enc_start,
    s.enc_end,
    s.v_lo,
    LEAST(s.v_lo, COALESCE(MIN(e.t_start), s.v_lo)) AS h_lo
  FROM step1 AS s
  LEFT JOIN enc AS e
    ON e.patient_id = s.patient_id
    AND e.id <> s.unit_id
    AND e.t_end >= s.v_lo - INTERVAL '1' HOUR
    AND e.t_end <= s.enc_start
  GROUP BY
    s.unit_id,
    s.patient_id,
    s.enc_start,
    s.enc_end,
    s.v_lo
)
SELECT
  unit_id,
  patient_id,
  enc_start,
  enc_end,
  v_lo,
  h_lo,
  h_lo - INTERVAL '{lookback_hours}' HOUR AS w_lo,
  enc_end + INTERVAL '{lookahead_hours}' HOUR AS w_hi
FROM step2;

CREATE TABLE members
WITH (format = 'PARQUET', write_compression = 'SNAPPY', external_location = '{loc}/members/') AS
SELECT DISTINCT
  b.unit_id,
  i.rtype,
  i.id
FROM unit_bound AS b
JOIN res_index AS i
  ON i.patient_id = b.patient_id
WHERE
  i.rtype IN ('Patient', 'Condition', 'Coverage')
  OR (
    i.rtype = 'Encounter' AND i.id = b.unit_id
  )
  OR i.encounter_id = b.unit_id
  OR i.part_of_id = b.unit_id
  OR i.t_start IS NULL
  OR b.w_lo IS NULL
  OR b.w_hi IS NULL
  OR (
    i.t_start <= b.w_hi AND i.t_end >= b.w_lo
  );

INSERT INTO members
SELECT DISTINCT
  m.unit_id,
  'Medication',
  i.med_ref_id
FROM members AS m
JOIN res_index AS i
  ON i.rtype = m.rtype AND i.id = m.id
JOIN res_index AS med
  ON med.rtype = 'Medication' AND med.id = i.med_ref_id
WHERE
  NOT i.med_ref_id IS NULL
  AND NOT EXISTS(
    SELECT
      1
    FROM members AS x
    WHERE
      x.unit_id = m.unit_id AND x.rtype = 'Medication' AND x.id = i.med_ref_id
  );

CREATE TABLE shared
WITH (format = 'PARQUET', write_compression = 'SNAPPY', external_location = '{loc}/shared/') AS
SELECT
  rtype,
  id
FROM res_index
WHERE
  rtype IN ('Location', 'Organization');
